   <title>Cat FAQ</title>
   <style>
     :root {
       color-scheme: light;
       --bg: #f4f7fb;
       --surface: rgba(255, 255, 255, 0.82);
       --surface-strong: #ffffff;
       --text: #14213d;
       --muted: #5f6c88;
       --accent: #5b7cff;
       --accent-strong: #3e5bf2;
       --border: rgba(91, 124, 255, 0.14);
       --shadow: 0 24px 80px rgba(20, 33, 61, 0.12);
       --radius: 22px;
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top left, rgba(91, 124, 255, 0.16), transparent 34%),
         radial-gradient(circle at top right, rgba(114, 234, 194, 0.18), transparent 28%),
         linear-gradient(180deg, #f8faff 0%, var(--bg) 100%);
       display: grid;
       place-items: center;
       padding: 32px 18px;
     }

     .page {
       width: min(100%, 920px);
       background: var(--surface);
       backdrop-filter: blur(16px);
       border: 1px solid rgba(255, 255, 255, 0.72);
       border-radius: 32px;
       box-shadow: var(--shadow);
       overflow: hidden;
     }

     .hero {
       padding: 64px 24px 36px;
       text-align: center;
       background:
         linear-gradient(135deg, rgba(91, 124, 255, 0.12), rgba(114, 234, 194, 0.08)),
         var(--surface-strong);
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 8px;
       padding: 8px 14px;
       border-radius: 999px;
       background: rgba(91, 124, 255, 0.1);
       color: var(--accent-strong);
       font-size: 0.84rem;
       font-weight: 700;
       letter-spacing: 0.04em;
       text-transform: uppercase;
     }

     h1 {
       margin: 18px auto 14px;
       max-width: 12ch;
       font-size: clamp(2.3rem, 5vw, 4.4rem);
       line-height: 1;
       letter-spacing: -0.04em;
     }

     .hero p {
       margin: 0 auto;
       max-width: 58ch;
       color: var(--muted);
       font-size: 1.05rem;
       line-height: 1.7;
     }

     .faq-list {
       padding: 8px 18px 24px;
     }

     .example {
       margin: 16px 0;
       padding: 8px;
       border-radius: var(--radius);
       background: rgba(255, 255, 255, 0.76);
       border: 1px solid var(--border);
       box-shadow: 0 10px 30px rgba(20, 33, 61, 0.06);
     }

     .question {
       width: 100%;
       border: 0;
       background: transparent;
       color: inherit;
       padding: 20px 22px;
       display: flex;
       align-items: center;
       justify-content: space-between;
       gap: 16px;
       font: inherit;
       font-size: 1.05rem;
       font-weight: 700;
       text-align: left;
       cursor: pointer;
       border-radius: 18px;
       transition: background-color 160ms ease, transform 160ms ease;
     }

     .question:hover,
     .question:focus-visible {
       background: rgba(91, 124, 255, 0.08);
       outline: none;
     }

     .question:focus-visible {
       box-shadow: 0 0 0 3px rgba(91, 124, 255, 0.24);
     }

     .icon {
       flex: 0 0 auto;
       width: 38px;
       height: 38px;
       display: grid;
       place-items: center;
       border-radius: 50%;
       background: rgba(91, 124, 255, 0.12);
       color: var(--accent-strong);
       transition: transform 180ms ease, background-color 180ms ease;
     }

